// Rouar のビルドが、依存を入れたあと、利用者のビルドの前に node で直接実行する。
// rouar CLI は @rouar/cli に分けたので、SDK には bin を置かず、この入口だけを残す。
//   node node_modules/@rouar/sdk/dist/prepare.mjs [プロジェクトのルート]
import { resolve } from "node:path";
import { prepare } from "./build/prepare";

const result = await prepare(resolve(process.cwd(), process.argv[2] ?? "."));
for (const action of result.actions) console.log(`rouar prepare: ${action}`);
for (const warning of result.warnings)
	console.warn(`rouar prepare: warning: ${warning}`);
